1	package release
2	
3	import (
4		"errors"
5		"strings"
6		"testing"
7		"time"
8	)
9	
10	const limitGrams = "9223372036854775.807"
11	
12	func openExecutingBatch(t *testing.T) *Store {
13		t.Helper()
14		s := openTestStore(t)
15		registerStandardRecipe(t, s, "recipe-1") // M1=100, M2=0.5, M3=0.010
16		if _, err := s.CreateBatch("b1", "B1", "R1", "v1", 10); err != nil {
17			t.Fatal(err)
18		}
19		if _, err := s.StartBatch("s1", "B1"); err != nil {
20			t.Fatal(err)
21		}
22		return s
23	}
24	
25	// 累计恰好达到上限可以成功，再追加哪怕 0.001 克也必须失败；
26	// 查询中的实投与差额必须准确，不得出现负数或错误的小数值。
27	func TestFeedingCumulativeLimit(t *testing.T) {
28		s := openExecutingBatch(t)
29	
30		// 先登记 9223372036854775.806 克。
31		f1, err := s.AddFeeding("f1", "B1", "M1", "9223372036854775.806", time.Now(), "张三")
32		if err != nil {
33			t.Fatalf("登记接近上限的数量应成功: %v", err)
34		}
35		if f1.Seq != 1 || f1.Grams != "9223372036854775.806" {
36			t.Fatalf("投料视图不正确: %+v", f1)
37		}
38		// 再登记 0.001 克，累计恰好等于上限，应成功。
39		f2, err := s.AddFeeding("f2", "B1", "M1", "0.001", time.Now(), "张三")
40		if err != nil {
41			t.Fatalf("累计恰好等于上限应成功: %v", err)
42		}
43		if f2.Seq != 2 {
44			t.Fatalf("第二次投料序号应为 2，得到 %d", f2.Seq)
45		}
46	
47		view, err := s.GetBatch("B1")
48		if err != nil {
49			t.Fatal(err)
50		}
51		var m1 MaterialRequirement
52		for _, m := range view.Materials {
53			if m.MaterialNo == "M1" {
54				m1 = m
55			}
56		}
57		if m1.ActualGrams != limitGrams {
58			t.Fatalf("累计实投应为上限 %s，得到 %s", limitGrams, m1.ActualGrams)
59		}
60		// 应投 = 100 × 10 = 1000，差额 = 上限 - 1000。
61		if m1.RequiredGrams != "1000" {
62			t.Fatalf("应投量不正确: %s", m1.RequiredGrams)
63		}
64		if m1.DifferenceGrams != "9223372036853775.807" {
65			t.Fatalf("差额不正确: %s", m1.DifferenceGrams)
66		}
67	
68		// 之后再登记 0.001 克必须失败。
69		_, err = s.AddFeeding("f3", "B1", "M1", "0.001", time.Now(), "张三")
70		if !errors.Is(err, ErrInvalidInput) {
71			t.Fatalf("超过上限应返回 ErrInvalidInput，得到 %v", err)
72		}
73		if !strings.Contains(err.Error(), "M1") {
74			t.Fatalf("错误信息应指明是哪种物料，得到 %v", err)
75		}
76	
77		// 失败后查询仍看到此前的完整投料与上限值，记录数不变。
78		view, err = s.GetBatch("B1")
79		if err != nil {
80			t.Fatal(err)
81		}
82		if len(view.Feedings) != 2 {
83			t.Fatalf("被拒绝的投料不应保存，得到 %d 条", len(view.Feedings))
84		}
85		for _, m := range view.Materials {
86			if m.MaterialNo == "M1" && m.ActualGrams != limitGrams {
87				t.Fatalf("拒绝后累计实投应仍为上限，得到 %s", m.ActualGrams)
88			}
89		}
90	}
91	
92	// 单次输入本身超过上限也必须拒绝，不能整数回绕成较小的合法克数后接受。
93	func TestSingleFeedingOverflowRejected(t *testing.T) {
94		s := openExecutingBatch(t)
95		cases := []string{
96			"9223372036854775.808",     // 比上限多 0.001 克
97			"9223372036854776",         // 整数部分已超上限
98			"18446744073709551.615",    // 2×上限，旧实现会回绕成负数
99			"18446744073709552",        // 旧实现会回绕成 0.384 克后被接受
100			"999999999999999999999999", // 远超 int64
101		}
102		for i, g := range cases {
103			reqNo := "big-" + string(rune('a'+i))
104			_, err := s.AddFeeding(reqNo, "B1", "M1", g, time.Now(), "张三")
105			if !errors.Is(err, ErrInvalidInput) {
106				t.Fatalf("单次输入 %s 应返回 ErrInvalidInput，得到 %v", g, err)
107			}
108		}
109	
110		view, err := s.GetBatch("B1")
111		if err != nil {
112			t.Fatal(err)
113		}
114		if len(view.Feedings) != 0 {
115			t.Fatalf("全部被拒绝时不应有投料记录，得到 %d 条", len(view.Feedings))
116		}
117		for _, m := range view.Materials {
118			if m.ActualGrams != "0" {
119				t.Fatalf("被拒绝的超大数量不应计入，物料 %s 实投为 %s", m.MaterialNo, m.ActualGrams)
120			}
121		}
122	
123		// 被拒绝的请求编号修正数量后仍可提交成功。
124		f, err := s.AddFeeding("big-a", "B1", "M1", "0.384", time.Now(), "张三")
125		if err != nil {
