487		}
488		if recipe.Name != "配方一" || len(recipe.Materials) != 2 {
489			t.Fatalf("配方数据不完整: %+v", recipe)
490		}
491		batch, err := s2.GetBatch("B1")
492		if err != nil {
493			t.Fatalf("重新打开后查询批次失败: %v", err)
494		}
495		if batch.Status != StatusClosed || batch.PlannedPortions != 10 || len(batch.Feedings) != 2 {
496			t.Fatalf("批次数据不完整: %+v", batch)
497		}
498		if batch.Materials[0].ActualGrams != "1000" || batch.Materials[1].ActualGrams != "5" {
499			t.Fatalf("投料数据不完整: %+v", batch.Materials)
500		}
501	
502		// 请求结果也在：幂等重放（投料时间相同，内容一致）。
503		replay, err := s2.AddFeeding("f1", "B1", "M1", "1000", fixedTime, "张三")
504		if err != nil {
505			t.Fatalf("重放投料请求失败: %v", err)
506		}
507		if replay.Seq != 1 {
508			t.Fatalf("重放应返回第一次成功的结果，seq 应为 1，得到 %d", replay.Seq)
509		}
510		batch2, _ := s2.GetBatch("B1")
511		if len(batch2.Feedings) != 2 {
512			t.Fatalf("重放不应新增投料，得到 %d 条", len(batch2.Feedings))
513		}
514	}
