package release

import (
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"sync"
	"testing"
	"time"
)

func openTestStore(t *testing.T) *Store {
	t.Helper()
	dir := t.TempDir()
	s, err := Open(dir)
	if err != nil {
		t.Fatalf("Open(%q) 失败: %v", dir, err)
	}
	t.Cleanup(func() { s.Close() })
	return s
}

func registerStandardRecipe(t *testing.T, s *Store, reqNo string) {
	t.Helper()
	_, err := s.RegisterRecipe(reqNo, "R1", "v1", "标准配方", []MaterialInput{
